INSERT INTO findings (doc, title, date, verdict, summary) VALUES
(136, 'Range book on individual stocks, 79 names, 20y daily', '2026-10-16', 'ACCEPTED', 'Containment range book, crypto-derived threshold applied blind (no fitting): +0.714% per episode, t=8.95, 8,560 episodes. All 8 sectors positive; 2001-12 +0.85%, 2013-26 +0.63%; ex-2008/09/20 t=8.78; 2021-26 t=4.35; 21/24 years positive; 90% of 79 stocks positive; known decliners +0.52% (survivorship contained). Shorts earn in bear years (2008 +7.5%, 2022 +2.1%), give back in bull years = hedge. Median hold 24 days: 1x/20 slots CAGR 7.5% maxDD 12.6% Sharpe 1.22. Better than ETFs (+0.28%) and crypto (+0.11%). Daily too slow to compound; 15m version forward-only. stock_range20.py, ingest_stocks.py'),
(137, 'Retest book on 20y ETFs and 79 stocks', '2026-10-16', 'REJECTED', 'Horizontal break/retest with native stop+target vs matched random control. ETFs: break +0.111R vs control +0.129R; stocks: break +0.113R vs control +0.140R. Retest timing beats break timing on paired setups (+0.20R ETF, +0.14R stocks) but retest absolute expectancy on stocks +0.073R is below control. No clean edge in any of the three universes. Transfer map ? -> X. retest_equity20.py');
INSERT INTO rules (rule, why, doc, added) VALUES
('The range book is the only book whose edge is a property of markets in general; widen its universe (ETFs, individual stocks) before building any new strategy.', 'Stocks +0.71%, ETFs +0.28%, crypto +0.11% per episode on identical accounting, rule applied unfitted. Keltner v1, patterns, retest all failed to transfer.', 136, '2026-10-16'),
('Stock-specific noise is chop, not gap: do not exclude individual equities from mean-reversion books on gap-risk grounds without testing.', 'Earnings gaps absorbed at worst tick; result still t=8.95 with worst episode -43.7% on intended capital (2.2% of equity at 20 slots).', 136, '2026-10-16');
